def motifs_vers_observations(apps, schema_editor):
    Avis = apps.get_model("avis", "Avis")
    for a in Avis.objects.exclude(motif_decision="").select_related("decision_par"):
        auteur = a.decision_par.login_windows if a.decision_par_id else "auteur inconnu"
        quand = a.decision_le.strftime("%d/%m/%Y") if a.decision_le else "date inconnue"
        note = f"Motif de décision repris de l'ancien champ ({auteur}, {quand}) : {a.motif_decision}"
        a.observations = f"{a.observations}\n\n{note}".strip()
        a.save(update_fields=["observations"])


